/**
 * Cryptographic utilities for CryptoGuard V1.0
 * Ed25519 signing and verification
 * 
 * Now using shared @cryptoguard/crypto package for consistency
 */

import {
  CryptoService,
  normalizePrivateKey as sharedNormalizePrivateKey,
  isValidPrivateKey as sharedIsValidPrivateKey,
  isValidPublicKey as sharedIsValidPublicKey,
  isValidSignature as sharedIsValidSignature
} from '@cryptoguard/crypto';
import { Ed25519Keypair } from '@mysten/sui/keypairs/ed25519';
import { decodeSuiPrivateKey } from '@mysten/sui/cryptography';
import { fromBase64 } from '@mysten/sui/utils';
import { MAX_PRIVATE_KEY_LENGTH } from './constants';

/**
 * Sign a message with Ed25519 private key
 */
export async function signMessage(message: string, privateKeyHex: string): Promise<string> {
  try {
    // Use the shared CryptoService which handles async correctly
    const result = await CryptoService.signMessage(message, privateKeyHex);
    return result.replace('0x', ''); // Remove 0x prefix for backward compatibility
  } catch (error) {
    throw new Error(`Failed to sign message: ${error instanceof Error ? error.message : String(error)}`);
  }
}

/**
 * Verify a signature with Ed25519 public key
 */
export async function verifySignature(
  message: string,
  signatureHex: string,
  publicKeyHex: string
): Promise<boolean> {
  try {
    // Add 0x prefix if needed for shared service compatibility
    const signature = signatureHex.startsWith('0x') ? signatureHex : '0x' + signatureHex;
    const publicKey = publicKeyHex.startsWith('0x') ? publicKeyHex : '0x' + publicKeyHex;
    
    return await CryptoService.verifySignature(message, signature, publicKey);
    
  } catch {
    // Signature verification failed - return false without logging sensitive details
    return false;
  }
}

/**
 * Generate Ed25519 public key from private key
 */
export async function getPublicKeyFromPrivate(privateKeyHex: string): Promise<string> {
  try {
    // Use the shared CryptoService which handles async correctly
    const result = await CryptoService.getPublicKey(privateKeyHex);
    return result.replace('0x', ''); // Remove 0x prefix for backward compatibility
  } catch (error) {
    throw new Error(`Failed to generate public key: ${error instanceof Error ? error.message : String(error)}`);
  }
}

/**
 * Generate secure random Ed25519 key pair
 */
export async function generateKeyPair(): Promise<{ privateKey: string; publicKey: string }> {
  try {
    // Use the shared CryptoService which handles async correctly
    const result = await CryptoService.generateKeyPair();
    return {
      privateKey: result.privateKey.replace('0x', ''),
      publicKey: result.publicKey.replace('0x', '')
    };
  } catch (error) {
    throw new Error(`Failed to generate key pair: ${error instanceof Error ? error.message : String(error)}`);
  }
}

/**
 * Calculate SHA256 hash of data
 */
export async function calculateSHA256(data: string | Uint8Array): Promise<string> {
  try {
    let inputData: string | Buffer;
    
    if (typeof data === 'string') {
      inputData = data;
    } else {
      inputData = Buffer.from(data);
    }
    
    const result = await CryptoService.hash(inputData);
    return result.replace('0x', ''); // Remove 0x prefix for backward compatibility
    
  } catch (error) {
    throw new Error(`Failed to calculate SHA256: ${error instanceof Error ? error.message : String(error)}`);
  }
}


/**
 * Parse private key from various formats into Ed25519Keypair
 * Supports: hex string (with or without 0x prefix), base64, suiprivkey (Bech32)
 *
 * @param privateKey - Private key in any supported format
 * @returns Ed25519Keypair instance
 * @throws Error if private key format is invalid
 */
export function parsePrivateKeyToKeypair(privateKey: string): Ed25519Keypair {
  const key = privateKey.trim();

  // Length guard to prevent DoS via excessive memory allocation
  if (key.length > MAX_PRIVATE_KEY_LENGTH) {
    throw new Error('Invalid private key: input too long');
  }

  // Try Sui wallet export format (suiprivkey1...)
  if (key.startsWith('suiprivkey')) {
    const parsed = decodeSuiPrivateKey(key);
    return Ed25519Keypair.fromSecretKey(parsed.secretKey);
  }

  // Try hex format with 0x prefix
  if (key.startsWith('0x') || key.startsWith('0X')) {
    const hexKey = key.substring(2);
    if (hexKey.length === 64 && /^[0-9a-fA-F]+$/.test(hexKey)) {
      const secretKey = Uint8Array.from(Buffer.from(hexKey, 'hex'));
      return Ed25519Keypair.fromSecretKey(secretKey);
    }
  }

  // Try raw hex without prefix
  if (/^[0-9a-fA-F]{64}$/.test(key)) {
    const secretKey = Uint8Array.from(Buffer.from(key, 'hex'));
    return Ed25519Keypair.fromSecretKey(secretKey);
  }

  // Try base64 format (length already validated above)
  try {
    const decoded = fromBase64(key);
    if (decoded.length === 32 || decoded.length === 64) {
      return Ed25519Keypair.fromSecretKey(decoded.slice(0, 32));
    }
  } catch {
    // Not base64, continue to error
  }

  throw new Error('Invalid private key format. Expected 64-char hex, suiprivkey, or base64 format.');
}

/**
 * Detect and normalize private key format to raw Ed25519 bytes (without 0x prefix)
 * Uses shared crypto package for consistent behavior
 */
export function normalizePrivateKey(privateKey: string): string {
  const result = sharedNormalizePrivateKey(privateKey);
  return result.replace('0x', ''); // Remove 0x prefix for backward compatibility
}

/**
 * Validate Ed25519 private key format (supports multiple formats)
 * Uses shared crypto package for consistent validation
 */
export function isValidPrivateKey(privateKey: string): boolean {
  return sharedIsValidPrivateKey(privateKey);
}

/**
 * Validate Ed25519 public key format
 * Uses shared crypto package for consistent validation
 */
export function isValidPublicKey(publicKeyHex: string): boolean {
  // Add 0x prefix if needed for shared service compatibility
  const publicKey = publicKeyHex.startsWith('0x') ? publicKeyHex : '0x' + publicKeyHex;
  return sharedIsValidPublicKey(publicKey);
}

/**
 * Validate signature format
 * Uses shared crypto package for consistent validation
 */
export function isValidSignature(signatureHex: string): boolean {
  // Add 0x prefix if needed for shared service compatibility
  const signature = signatureHex.startsWith('0x') ? signatureHex : '0x' + signatureHex;
  return sharedIsValidSignature(signature);
}