/**
 * CryptoGuard Action - SLSA Level 3 Mode
 *
 * This action receives pre-generated SLSA provenance from slsa-github-generator
 * and uploads it to Walrus + updates Sui blockchain.
 *
 * Flow:
 * 1. Read SLSA provenance file (from isolated VM)
 * 2. Read manifest.json (framework routing)
 * 3. Verify domain ownership (signature + blockchain lookup)
 * 4. Upload quilt to Walrus (provenance + manifest)
 * 5. Update Sui blockchain
 */

import * as core from '@actions/core';
import * as github from '@actions/github';
import * as fs from 'fs/promises';
import { WalrusClient, WalrusError } from './walrus-client';
import { CryptoGuardSuiClient, SuiError } from './sui-client';
import {
  DEFAULT_GAS_BUDGET_MIST,
  TESTNET_REGISTRY_ID,
  TESTNET_PACKAGE_ID,
  MAINNET_REGISTRY_ID,
  MAINNET_PACKAGE_ID,
  SUI_TESTNET_RPC_URL,
  SUI_MAINNET_RPC_URL,
  WALRUS_TESTNET_PUBLISHER_URL,
  WALRUS_TESTNET_AGGREGATOR_URL,
  WALRUS_MAINNET_PUBLISHER_URL,
  WALRUS_MAINNET_AGGREGATOR_URL,
  WALRUS_UPLOAD_TIMEOUT_MS,
} from './constants';

interface ActionInputs {
  domain: string;
  provenanceFile: string;
  manifestFile: string;
  network: string;
  privateKey: string;
  suiRpcUrl: string;
  registryId: string;
  packageId: string;
  walrusPublisherUrl: string;
  walrusAggregatorUrl: string;
  gasBudget: string;
}

/**
 * Main entry point
 */
async function run(): Promise<void> {
  try {
    const inputs = parseInputs();

    core.info('🚀 CryptoGuard SLSA Level 3 Deployment');
    core.info(`Domain: ${inputs.domain} | Network: ${inputs.network}`);
    core.info('🔐 Mode: SLSA Level 3 (Provenance from Isolated VM)');
    core.info('');

    // Execute deployment
    const result = await executeDeployment(inputs);

    // Set outputs
    core.setOutput('quilt-blob-id', result.quiltBlobId);
    core.setOutput('tx-digest', result.txDigest);
    core.setOutput('version', result.newVersion);
    core.setOutput('site-record-id', result.siteRecordId);

    // Final summary
    core.info('');
    core.info('✅ Deployment Complete');
    core.info(`Version: ${result.newVersion} | Gas: ${(result.gasUsed / 1_000_000_000).toFixed(4)} SUI`);
    core.info(`Transaction: https://suiscan.xyz/${inputs.network}/tx/${result.txDigest}`);
    core.info(`Site: https://${inputs.domain}`);
    core.info('🔐 SLSA Level 3: Provenance generated in isolated VM');

  } catch (error) {
    handleError(error);
  }
}

/**
 * Parse action inputs
 */
function parseInputs(): ActionInputs {
  const network = core.getInput('network') || 'testnet';

  const inputs: ActionInputs = {
    domain: core.getInput('domain', { required: true }),
    provenanceFile: core.getInput('provenance-file', { required: true }),
    manifestFile: core.getInput('manifest-file', { required: true }),
    network,
    privateKey: process.env.PRIVATE_KEY || process.env.ED25519_PRIVATE_KEY || '',
    suiRpcUrl: core.getInput('sui-rpc-url') ||
      (network === 'mainnet' ? SUI_MAINNET_RPC_URL : SUI_TESTNET_RPC_URL),
    registryId: network === 'mainnet' ? MAINNET_REGISTRY_ID : TESTNET_REGISTRY_ID,
    packageId: network === 'mainnet' ? MAINNET_PACKAGE_ID : TESTNET_PACKAGE_ID,
    walrusPublisherUrl: core.getInput('walrus-publisher-url') ||
      (network === 'mainnet' ? WALRUS_MAINNET_PUBLISHER_URL : WALRUS_TESTNET_PUBLISHER_URL),
    walrusAggregatorUrl: core.getInput('walrus-aggregator-url') ||
      (network === 'mainnet' ? WALRUS_MAINNET_AGGREGATOR_URL : WALRUS_TESTNET_AGGREGATOR_URL),
    gasBudget: core.getInput('gas-budget') || String(DEFAULT_GAS_BUDGET_MIST),
  };

  // Validate
  if (!inputs.privateKey) {
    throw new Error('PRIVATE_KEY environment variable is required');
  }

  const domainRegex = /^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
  if (!domainRegex.test(inputs.domain)) {
    throw new Error(`Invalid domain format: ${inputs.domain}`);
  }

  return inputs;
}

interface DeploymentResult {
  quiltBlobId: string;
  txDigest: string;
  newVersion: string;
  siteRecordId: string;
  gasUsed: number;
}

/**
 * Execute deployment workflow
 */
async function executeDeployment(inputs: ActionInputs): Promise<DeploymentResult> {
  // Step 1: Read SLSA provenance
  core.info('Step 1: Read SLSA Provenance');

  const provenanceContent = await fs.readFile(inputs.provenanceFile, 'utf-8');
  const provenanceRaw = JSON.parse(provenanceContent);

  // SLSA provenance is wrapped in a DSSE envelope with base64-encoded payload
  let provenance: any;
  let subjectCount = 0;

  if (provenanceRaw.dsseEnvelope?.payload) {
    // Decode the base64 payload to get the actual in-toto statement
    const payloadDecoded = Buffer.from(provenanceRaw.dsseEnvelope.payload, 'base64').toString('utf-8');
    provenance = JSON.parse(payloadDecoded);
    subjectCount = provenance.subject?.length || 0;
  } else if (provenanceRaw.payload) {
    // Alternative envelope format
    const payloadDecoded = Buffer.from(provenanceRaw.payload, 'base64').toString('utf-8');
    provenance = JSON.parse(payloadDecoded);
    subjectCount = provenance.subject?.length || 0;
  } else {
    // Direct in-toto statement (no envelope)
    provenance = provenanceRaw;
    subjectCount = provenance.subject?.length || 0;
  }

  core.info(`✓ Loaded provenance: ${subjectCount} subjects`);

  // Step 2: Read manifest
  core.info('Step 2: Read Manifest');

  let manifest: any;
  try {
    const manifestContent = await fs.readFile(inputs.manifestFile, 'utf-8');
    manifest = JSON.parse(manifestContent);

    // Validate manifest
    const { validateManifest } = await import('@cmdoss/cryptoguard-manifest-core');
    validateManifest(manifest);

    core.info(`✓ Manifest: ${manifest.framework} v${manifest.frameworkVersion}`);
  } catch (error: any) {
    // Only create blank manifest if file not found
    // For other errors (parse/validation), fail explicitly
    if (error?.code === 'ENOENT') {
      core.info('  Manifest file not found, creating blank manifest...');
      const { MANIFEST_VERSION } = await import('@cmdoss/cryptoguard-manifest-core');
      manifest = {
        version: MANIFEST_VERSION,
        framework: 'unknown',
        frameworkVersion: 'unknown',
        sources: [{ dir: '.', serveAt: '/' }],
      };
      core.info(`✓ Blank manifest created`);
    } else {
      // Re-throw parse/validation errors - don't silently deploy with wrong manifest
      const errorMessage = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid manifest file: ${errorMessage}`);
    }
  }

  // Step 3: Verify domain ownership
  core.info('Step 3: Verify Domain Ownership');

  const suiClient = new CryptoGuardSuiClient({
    network: inputs.network as 'testnet' | 'mainnet' | 'localnet',
    rpcUrl: inputs.suiRpcUrl,
    registryId: inputs.registryId,
    packageId: inputs.packageId || undefined,
    gasBudget: inputs.gasBudget,
  });

  // Lookup domain on blockchain
  const domainRecord = await suiClient.lookupDomain(inputs.domain);

  if (!domainRecord) {
    throw new Error(
      `Domain not registered: ${inputs.domain}\n\n` +
      `Register your domain first:\n` +
      `  cryptoguard register ${inputs.domain}`
    );
  }

  core.info(`✓ Domain verified on blockchain`);
  core.info(`  Site Record: ${domainRecord.id.substring(0, 16)}...`);
  core.info(`  Current Version: ${domainRecord.currentVersion}`);

  const siteRecordId = domainRecord.id;
  const currentVersion = Number(domainRecord.currentVersion);

  // Step 4: Upload quilt to Walrus
  core.info('Step 4: Upload Quilt to Walrus');

  const walrusClient = new WalrusClient({
    publisherUrl: inputs.walrusPublisherUrl,
    aggregatorUrl: inputs.walrusAggregatorUrl,
    timeout: WALRUS_UPLOAD_TIMEOUT_MS,
    maxRetries: 3,
    network: inputs.network as 'mainnet' | 'testnet',
    privateKey: inputs.privateKey,
    suiRpcUrl: inputs.suiRpcUrl,
  });

  // Create quilt with SLSA provenance + manifest
  // Store the original DSSE envelope (with signatures) for verifiers
  const quilt = {
    attestation: provenanceRaw, // Full envelope with signatures
    attestation_decoded: provenance, // Decoded statement for convenience
    manifest: manifest,
  };

  const quiltJson = JSON.stringify(quilt);
  const quiltBuffer = Buffer.from(quiltJson, 'utf-8');

  const uploadResult = await walrusClient.uploadBlob(quiltBuffer);

  core.info(`✓ Quilt uploaded: ${uploadResult.blobId.substring(0, 16)}...`);
  core.info(`  Size: ${(quiltBuffer.length / 1024).toFixed(1)} KB`);
  core.info(`  Subjects: ${subjectCount} file hashes`);

  // Step 5: Update blockchain
  core.info('Step 5: Update Blockchain');

  const deploymentData = {
    quilt_blob_id: uploadResult.blobId,
    files_manifest_hash: '', // Not needed - hashes are in provenance
    total_files: subjectCount,
    total_size_bytes: quiltBuffer.length,
    github_repo: `${github.context.repo.owner}/${github.context.repo.repo}`,
    github_commit_sha: github.context.sha,
    github_workflow_ref: github.context.ref,
    github_run_id: github.context.runId,
  };

  core.info('  Signing transaction with your private key...');
  const txResult = await suiClient.updateSiteDirect(
    inputs.privateKey,
    siteRecordId,
    deploymentData
  );

  core.info(`✓ Blockchain updated`);
  core.info(`  Version: ${currentVersion} → ${txResult.newVersion}`);
  core.info(`  Gas: ${(Number(txResult.gasUsed) / 1_000_000_000).toFixed(4)} SUI`);
  core.info(`  TX: ${txResult.digest.substring(0, 16)}...`);

  return {
    quiltBlobId: uploadResult.blobId,
    txDigest: txResult.digest,
    newVersion: txResult.newVersion || String(currentVersion + 1),
    siteRecordId,
    gasUsed: Number(txResult.gasUsed) || 0,
  };
}

/**
 * Handle errors with user-friendly messages
 */
function handleError(error: unknown): void {
  if (error instanceof WalrusError) {
    core.error(`\n❌ Walrus Upload Failed (${error.code})`);
    core.error(error.message);
    core.setFailed(`Walrus error: ${error.code}`);
    return;
  }

  if (error instanceof SuiError) {
    core.error(`\n❌ Blockchain Error (${error.code})`);
    core.error(error.message);

    if (error.code === 'INSUFFICIENT_GAS') {
      core.error('\nGet SUI from https://faucet.sui.io (testnet)');
    } else if (error.code === 'DOMAIN_NOT_REGISTERED') {
      core.error('\nRegister domain: cryptoguard register YOUR_DOMAIN');
    }

    core.setFailed(`Blockchain error: ${error.code}`);
    return;
  }

  const message = error instanceof Error ? error.message : String(error);
  core.error(`\n❌ Deployment Failed`);
  core.error(message);
  core.setFailed(message);
}

// Run if executed directly
if (require.main === module) {
  run();
}

export { run };
