import * as core from '@actions/core';
import { WalrusClient as WalrusSdkClient, TESTNET_WALRUS_PACKAGE_CONFIG, MAINNET_WALRUS_PACKAGE_CONFIG } from '@mysten/walrus';
import { Ed25519Keypair } from '@mysten/sui/keypairs/ed25519';
import { parsePrivateKeyToKeypair } from './crypto-utils';
import {
  WALRUS_DEFAULT_TIMEOUT_MS,
  WALRUS_MAX_TIP_MIST,
  SUI_TESTNET_RPC_URL,
  SUI_MAINNET_RPC_URL,
} from './constants';

/**
 * Configuration for Walrus client
 */
export interface WalrusClientConfig {
  publisherUrl: string;
  aggregatorUrl?: string;
  timeout?: number;
  maxRetries?: number;
  // New SDK-based configuration
  network?: 'mainnet' | 'testnet';
  privateKey?: string;  // User's private key for payment
  suiRpcUrl?: string;
}

/**
 * Result of a Walrus blob upload
 */
export interface WalrusBlobInfo {
  blobId: string;
  size: number;
  uploadDuration: number;
}

/**
 * Error thrown by Walrus operations
 */
export class WalrusError extends Error {
  constructor(
    message: string,
    public code: string,
    public details?: any
  ) {
    super(message);
    this.name = 'WalrusError';
  }
}

/**
 * Quilt structure containing attestation + manifest
 * This is the ONLY blob uploaded to Walrus - contains 2 files:
 * 1. attestation.json - Sigstore attestation with files_manifest (all file hashes)
 * 2. manifest.json - Framework routing info for SSR path mappings
 */
export interface CryptoGuardQuilt {
  version: string;
  // The attestation contains the files_manifest with all SHA256 hashes
  attestation: {
    sigstore_bundle: any;  // Sigstore DSSE envelope
    files_manifest: {
      files: Array<{
        path: string;
        content_hash: string;  // SHA256 hash
        size_bytes: number;
      }>;
      total_files: number;
      total_size_bytes: number;
    };
    slsa_provenance: any;
    github_context: any;
  };
  // Framework manifest for SSR path routing
  manifest: {
    version: string;
    framework: string;
    frameworkVersion: string;
    sources: Array<{
      dir: string;
      serveAt: string;
    }>;
  };
  // Metadata
  metadata: {
    domain: string;
    created_at: string;
    deployment_type: string;
  };
}

/**
 * Quilt deployment result
 */
export interface QuiltDeployment {
  blobId: string;
  quilt: CryptoGuardQuilt;
  totalSize: number;
}

/**
 * Client for interacting with Walrus decentralized storage
 * Handles file uploads and blob verification with quilt support
 *
 * Uses @mysten/walrus SDK for actual uploads with payment signer
 */
export class WalrusClient {
  private readonly publisherUrl: string;
  private readonly aggregatorUrl: string;
  private readonly timeout: number;
  private readonly maxRetries: number;
  private readonly network: 'mainnet' | 'testnet';
  private readonly walrusSdk: WalrusSdkClient | null = null;
  private readonly signer: Ed25519Keypair | null = null;

  constructor(config: WalrusClientConfig) {
    this.publisherUrl = config.publisherUrl;
    this.aggregatorUrl = config.aggregatorUrl || config.publisherUrl.replace('publisher', 'aggregator');
    this.timeout = config.timeout || WALRUS_DEFAULT_TIMEOUT_MS;
    this.maxRetries = config.maxRetries || 3;
    this.network = config.network || 'testnet';

    // Initialize SDK with payment signer if private key is provided
    if (config.privateKey) {
      try {
        // Parse private key (supports both hex and suiprivkey formats)
        this.signer = this.parsePrivateKey(config.privateKey);

        const packageConfig = this.network === 'mainnet'
          ? MAINNET_WALRUS_PACKAGE_CONFIG
          : TESTNET_WALRUS_PACKAGE_CONFIG;

        // Use upload relay for reliable uploads (recommended by Walrus SDK docs)
        const uploadRelayHost = this.network === 'mainnet'
          ? 'https://upload-relay.walrus.space'
          : 'https://upload-relay.testnet.walrus.space';

        this.walrusSdk = new WalrusSdkClient({
          network: this.network,
          packageConfig,
          suiRpcUrl: config.suiRpcUrl || (this.network === 'mainnet'
            ? SUI_MAINNET_RPC_URL
            : SUI_TESTNET_RPC_URL),
          // Upload relay provides more reliable uploads by handling node coordination
          uploadRelay: {
            host: uploadRelayHost,
            sendTip: {
              max: WALRUS_MAX_TIP_MIST,
            },
          },
        });

        core.info(`Walrus SDK using upload relay: ${uploadRelayHost}`);

        const signerAddress = this.signer.toSuiAddress();
        core.info(`Walrus SDK initialized with signer: ${signerAddress.substring(0, 16)}...`);
      } catch (error) {
        core.warning(`Failed to initialize Walrus SDK with signer: ${error}. Falling back to HTTP-based uploads.`);
        this.signer = null;
        this.walrusSdk = null;
      }
    }
  }

  /**
   * Parse private key from various formats
   * Uses shared parsePrivateKeyToKeypair from crypto-utils
   */
  private parsePrivateKey(privateKey: string) {
    return parsePrivateKeyToKeypair(privateKey);
  }

  /**
   * Upload a file to Walrus storage
   * Uses SDK with payment signer if available, otherwise falls back to HTTP
   * @param fileContent - File content as Buffer or string
   * @param fileName - Optional file name for logging
   * @returns Blob information including blob ID
   */
  async uploadBlob(fileContent: Buffer | string, fileName?: string): Promise<WalrusBlobInfo> {
    const startTime = Date.now();
    const content = Buffer.isBuffer(fileContent) ? fileContent : Buffer.from(fileContent, 'utf-8');

    core.debug(`Uploading blob${fileName ? ` (${fileName})` : ''} to Walrus (${content.length} bytes)`);

    // Use SDK with signer if available (preferred method with payment)
    if (this.walrusSdk && this.signer) {
      return this.uploadBlobWithSdk(content, fileName);
    }

    // Fallback to HTTP-based upload (may not work on public publishers without payment)
    return this.uploadBlobWithHttp(content, fileName);
  }

  /**
   * Upload blob using @mysten/walrus SDK with payment signer
   */
  private async uploadBlobWithSdk(content: Buffer, fileName?: string): Promise<WalrusBlobInfo> {
    const startTime = Date.now();

    if (!this.walrusSdk || !this.signer) {
      throw new WalrusError('Walrus SDK not initialized', 'SDK_NOT_INITIALIZED');
    }

    let lastError: Error | undefined;
    const maxAttempts = 5; // Increased retries for network issues

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        core.debug(`SDK upload attempt ${attempt}/${maxAttempts}${fileName ? ` for ${fileName}` : ''}`);

        // Use SDK writeBlob with signer for payment
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const result = await this.walrusSdk.writeBlob({
          blob: new Uint8Array(content),
          epochs: 5, // Store for 5 epochs (~5 days on testnet)
          deletable: true,
          signer: this.signer as any, // Type cast needed for SDK compatibility
        });

        const uploadDuration = Date.now() - startTime;

        core.debug(`✅ SDK blob uploaded successfully: ${result.blobId} (${uploadDuration}ms)`);

        return {
          blobId: result.blobId,
          size: content.length,
          uploadDuration,
        };

      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));
        const errorMsg = lastError.message.toLowerCase();

        // Check for specific error types
        if (errorMsg.includes('insufficient') || errorMsg.includes('balance')) {
          throw new WalrusError(
            `Insufficient balance for Walrus upload. Please ensure your wallet has enough SUI (for gas) and WAL tokens (for storage). Error: ${lastError.message}`,
            'INSUFFICIENT_BALANCE',
            { lastError: lastError.message }
          );
        }

        if (attempt < maxAttempts) {
          const delay = Math.min(2000 * Math.pow(2, attempt - 1), 15000); // Longer delays: 2s, 4s, 8s, 15s
          core.warning(`SDK upload attempt ${attempt} failed, retrying in ${delay}ms: ${lastError.message}`);
          await this.sleep(delay);
        }
      }
    }

    // Provide helpful error message
    const errorMsg = lastError?.message || 'Unknown error';
    let helpText = '';
    if (errorMsg.includes('Too many failures') || errorMsg.includes('fetch failed')) {
      helpText = '\n\nPossible causes:\n' +
        '1. Insufficient WAL tokens - Get WAL from Walrus testnet faucet\n' +
        '2. Insufficient SUI for gas - Get SUI from https://faucet.sui.io\n' +
        '3. Walrus network congestion - Try again later\n' +
        '4. Network connectivity issues - Check your connection';
    }

    throw new WalrusError(
      `Failed to upload blob with SDK after ${maxAttempts} attempts: ${errorMsg}${helpText}`,
      'SDK_UPLOAD_FAILED',
      { lastError: errorMsg }
    );
  }

  /**
   * Upload blob using HTTP PUT (legacy method, may not work on public publishers)
   */
  private async uploadBlobWithHttp(content: Buffer, fileName?: string): Promise<WalrusBlobInfo> {
    const startTime = Date.now();

    core.warning('Using HTTP-based Walrus upload (no payment signer). This may fail on public publishers.');

    let lastError: Error | undefined;

    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);

        const response = await (globalThis.fetch || fetch)(`${this.publisherUrl}/v1/blobs`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/octet-stream',
          },
          body: content as BodyInit,
          signal: controller.signal as AbortSignal,
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
          const errorText = await response.text();
          throw new WalrusError(
            `Walrus upload failed: ${response.status} ${response.statusText}`,
            'UPLOAD_FAILED',
            { status: response.status, body: errorText }
          );
        }

        const result = await response.json() as any;

        // Walrus returns different response formats depending on whether blob is new or already exists
        let blobId: string;

        if (result.newlyCreated) {
          // New blob was created
          blobId = result.newlyCreated.blobObject?.blobId || result.newlyCreated.blobId;
        } else if (result.alreadyCertified) {
          // Blob already exists and is certified
          blobId = result.alreadyCertified.blobId || result.alreadyCertified.blobObject?.blobId;
        } else {
          throw new WalrusError(
            'Unexpected Walrus response format',
            'INVALID_RESPONSE',
            { response: result }
          );
        }

        if (!blobId) {
          throw new WalrusError(
            'Blob ID not found in Walrus response',
            'MISSING_BLOB_ID',
            { response: result }
          );
        }

        const uploadDuration = Date.now() - startTime;

        core.debug(`✅ HTTP blob uploaded successfully: ${blobId} (${uploadDuration}ms)`);

        return {
          blobId,
          size: content.length,
          uploadDuration,
        };

      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));

        if (error instanceof WalrusError) {
          // Don't retry on certain error codes
          if (error.code === 'INVALID_RESPONSE' || error.code === 'MISSING_BLOB_ID') {
            throw error;
          }
        }

        if (attempt < this.maxRetries) {
          const delay = Math.min(1000 * Math.pow(2, attempt - 1), 5000); // Exponential backoff, max 5s
          core.warning(`HTTP upload attempt ${attempt} failed, retrying in ${delay}ms: ${lastError.message}`);
          await this.sleep(delay);
        }
      }
    }

    throw new WalrusError(
      `Failed to upload blob after ${this.maxRetries} attempts: ${lastError?.message}`,
      'MAX_RETRIES_EXCEEDED',
      { lastError: lastError?.message }
    );
  }

  /**
   * Upload multiple blobs in parallel
   * @param files - Map of file path to file content
   * @param concurrency - Max number of parallel uploads
   * @returns Map of file path to blob ID
   */
  async uploadBlobs(
    files: Record<string, Buffer | string>,
    concurrency: number = 5
  ): Promise<Record<string, string>> {
    const entries = Object.entries(files);
    const results: Record<string, string> = {};

    core.debug(`Uploading ${entries.length} files (concurrency: ${concurrency})`);

    // Process in batches
    for (let i = 0; i < entries.length; i += concurrency) {
      const batch = entries.slice(i, i + concurrency);

      const batchResults = await Promise.all(
        batch.map(async ([path, content]) => {
          const blobInfo = await this.uploadBlob(content, path);
          core.debug(`Uploaded ${path} → ${blobInfo.blobId}`);
          return { path, blobId: blobInfo.blobId };
        })
      );

      for (const { path, blobId } of batchResults) {
        results[path] = blobId;
      }
    }

    return results;
  }

  /**
   * Verify that a blob exists in Walrus
   * @param blobId - Blob ID to verify
   * @returns True if blob exists and is accessible
   */
  async verifyBlob(blobId: string): Promise<boolean> {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), this.timeout);

      const response = await (globalThis.fetch || fetch)(`${this.aggregatorUrl}/v1/${blobId}`, {
        method: 'HEAD',
        signal: controller.signal as AbortSignal,
      });

      clearTimeout(timeoutId);

      return response.ok;
    } catch (error) {
      core.warning(`Failed to verify blob ${blobId}: ${error instanceof Error ? error.message : String(error)}`);
      return false;
    }
  }

  /**
   * Upload a single quilt containing attestation + manifest
   *
   * CORRECT ARCHITECTURE:
   * - Single quilt blob uploaded to Walrus
   * - Contains 2 logical files: attestation.json + manifest.json
   * - attestation.json contains files_manifest with all SHA256 hashes
   * - manifest.json contains framework routing info for SSR sites
   * - NO individual file blobs are uploaded (hashes only, not content)
   *
   * @param filesManifest - Files manifest with hashes (from file scanning)
   * @param attestation - Sigstore attestation data
   * @param manifest - CryptoGuard manifest (framework routing info)
   * @param domain - Domain being deployed
   * @returns Quilt deployment result with single blob_id
   */
  async uploadQuilt(
    filesManifest: {
      files: Array<{ path: string; content_hash: string; size_bytes: number }>;
      total_files: number;
      total_size_bytes: number;
    },
    attestation: {
      sigstore_bundle?: any;
      slsa_provenance: any;
      attested_provenance?: any;
      github_context: any;
    },
    manifest: {
      version: string;
      framework: string;
      frameworkVersion: string;
      sources: Array<{ dir: string; serveAt: string }>;
    },
    domain: string
  ): Promise<QuiltDeployment> {
    core.info(`  Creating quilt with attestation + manifest...`);

    // Build the quilt structure
    const quilt: CryptoGuardQuilt = {
      version: '1.0',
      attestation: {
        sigstore_bundle: attestation.sigstore_bundle || attestation.attested_provenance || null,
        files_manifest: filesManifest,
        slsa_provenance: attestation.slsa_provenance,
        github_context: attestation.github_context,
      },
      manifest: manifest,
      metadata: {
        domain: domain,
        created_at: new Date().toISOString(),
        deployment_type: 'cryptoguard-quilt-v1',
      },
    };

    // Serialize and upload
    const quiltJson = JSON.stringify(quilt, null, 2);
    const quiltBuffer = Buffer.from(quiltJson, 'utf-8');

    core.debug(`Quilt size: ${quiltBuffer.length} bytes`);
    core.debug(`Files in manifest: ${filesManifest.total_files}`);

    const blobInfo = await this.uploadBlob(quiltBuffer, 'cryptoguard-quilt.json');

    core.info(`  ✓ Quilt uploaded: ${blobInfo.blobId.substring(0, 16)}...`);
    core.info(`    - attestation.json: ${filesManifest.total_files} file hashes`);
    core.info(`    - manifest.json: ${manifest.framework} v${manifest.frameworkVersion}`);

    return {
      blobId: blobInfo.blobId,
      quilt: quilt,
      totalSize: blobInfo.size,
    };
  }

  /**
   * Sleep for specified milliseconds
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}
